import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>你手里有一张照片，报名表却不接受超过50KB的文件。掌握了步骤之后，整个操作大概只要两分钟。</p>\n<p>这篇指南会带你走完整个流程。你会准备好合适的原图、跑一遍压缩器、检查结果，并解决最常见的卡点。</p>\n<p>不需要安装任何软件。下面所有步骤在普通浏览器里都能完成，电脑和手机都可以。</p>\n<h2 id=\"before-you-start\">开始之前：先拿到合适的原图</h2>\n<p>从你手里画质最好的原图开始。相机直出的照片，压出来的效果远比已经缩过一次的副本好。</p>\n<p>如果照片是别人通过聊天软件发来的，它可能已经被压过一次了。效果不好时，找对方要一份原文件。</p>\n<p>压缩之前，先看清报名网站的规则。记下文件大小上限、要求的像素尺寸，以及接受哪些格式。</p>\n<p>把这三个数字写下来。盲目压缩是浪费时间，因为即使压出了完美的50KB，格式不对还是会被拒绝。</p>\n<h2 id=\"step-1-open-the-tool\">第一步：打开50KB压缩工具</h2>\n<p>在浏览器里打开<a href=\"/zh/tupian-yasuo-dao-50kb/\">图片压缩到50KB工具</a>。页面加载出压缩器，你的文件始终留在自己的设备上。</p>\n<p>不需要注册账号。没有注册步骤，也没有上传排队，打开就能直接用。</p>\n<p>如果用手机操作，就用你平时用的浏览器。上传按钮会直接打开手机相册。</p>\n<p>报名页面也另外开一个标签页留着。操作的时候，对照着它的规则会方便很多。</p>\n<h2 id=\"step-2-upload\">第二步：上传图片</h2>\n<p>把图片拖进上传区域，或者点按钮选择文件。支持JPG、PNG、WebP和HEIC，单个文件最大25MB。</p>\n<p>证件照的话，直接上传全分辨率的原图。缩小的工作交给工具，你不用先自己改尺寸。</p>\n<p>扫描签名的话，上传最干净的那次扫描。白底的扫描件比斜着拍的纸张照片好压得多。</p>\n<p>文件如果超过25MB，先调整尺寸或重新导出一次。拿手机截一张图当捷径很糟糕，截图会带入噪点。</p>\n<h2 id=\"step-3-let-it-search\">第三步：让工具找到最佳画质</h2>\n<p>图片加载进来后，工具会运行二分画质搜索。它会不断测试不同的画质档位，直到找到既能塞进50KB、画质又最高的那一个。</p>\n<p>你不用自己选画质数值。这个搜索的存在，就是为了让你不用猜。</p>\n<p>留意结果上的“小于50KB”徽章。有这个徽章，就说明文件通过了上限，可以放心提交。</p>\n<p>如果工具提示目标没达成，也别慌。下面的修复方法在大多数情况下都能解决问题。</p>\n<h2 id=\"step-4-preview\">第四步：下载之前先预览</h2>\n<p>下载之前，一定要先预览压缩后的图片。文件大小对了，不代表画面本身没受损。</p>\n<p>放大看看重要的部位。人像就检查眼睛和脸部轮廓，证件就检查最小的那行字。</p>\n<p>如果工具有对比视图，可以把结果和原图并排看一看。细微的差别很正常，字看不清就不正常。</p>\n<p>预览效果不对时，先换个格式再试。把PNG换成JPG，常常能立刻解决目标没达成的问题。</p>\n<h2 id=\"step-5-download\">第五步：下载，并给文件起个清楚的名字</h2>\n<p>下载压缩好的文件，给它起个清楚的名字。passport-photo-50kb.jpg这样的名字，几个月后一看就知道是什么。</p>\n<p>原图也要留着。如果报名网站拒绝了压缩版，你不用再到处找原图，可以直接重试。</p>\n<p>在设备上确认一下下载文件的大小。它应该略低于50KB，通常在48KB到49.9KB之间。</p>\n<p>留出这点余量是故意的。报名系统按字节数来判断，略低于上限能帮你避开不同系统四舍五入的差异。</p>\n<h2 id=\"fixing-a-missed-target\">目标没达成时怎么修？</h2>\n<p>目标没达成，通常只有三个原因：格式不对、尺寸被锁死，或者原图细节太多。</p>\n<p>第一，把输出格式换成JPG。PNG格式的照片常常根本压不到50KB，不管你怎么缩小都没用。</p>\n<p>第二，允许缩放尺寸。工具会逐步减小像素尺寸，稍微缩一点，目标常常就解锁了。</p>\n<p>第三，裁掉空白或杂乱的边缘。背景杂乱的照片，会把KB浪费在没人看的地方。</p>\n<h2 id=\"passport-photo-tips\">证件照和身份证照片的小技巧</h2>\n<p>护照类网站常常既要求尺寸精确，又要求文件大小。常见的一对要求是600×600像素、小于50KB。</p>\n<p>先找一张本来就接近要求形状的照片。把一张宽幅风景照裁成正方形，等于扔掉了大部分画面。</p>\n<p>用干净的浅色背景。杂乱的背景会增加细节，既吃掉KB，又分散对脸部的注意力。</p>\n<p>脸部大小的规则也要看。很多网站要求脸部占画面的固定比例，脸太小的话，压缩是修不好的。</p>\n<h2 id=\"signature-scan-tips\">签名和扫描件的小技巧</h2>\n<p>签名压起来非常轻松，因为它基本是白色空白。一张干净的扫描件可以轻松到达50KB，画质还有余量。</p>\n<p>扫描分辨率要适度。300 DPI完全够用，1200 DPI只会造出一个巨大的文件，然后被迫压得更狠。</p>\n<p>上传之前先把扫描件摆正。倾斜的签名会在边角浪费像素，什么用都没有。</p>\n<p>如果压缩后签名看起来发灰而不是黑色，上传前稍微提高一点对比度。深色的墨水比浅浅的铅笔线更耐压。</p>\n<h2 id=\"phone-workflow\">全程用手机操作</h2>\n<p>大多数人为报名表压缩照片时都在用手机。流程是一样的，只是有几个小差别。</p>\n<p>从相册里选原图，不要选从聊天软件里保存的副本。聊天软件会在你看到照片之前就先把它压小。</p>\n<p>苹果手机的照片可能是HEIC格式。工具支持HEIC，直接上传就行，不用先转换。</p>\n<p>下载之后，在“文件”应用里检查一下。确认大小确实小于50KB，再切回报名页面。</p>\n<h2 id=\"checking-your-result\">如何正确检查结果</h2>\n<p>打开下载好的文件，用全尺寸看一遍。缩略图会藏住问题，报名审核的人却看得见。</p>\n<p>把图片里的文字大声读出来。如果每个字都能读出来，压缩就算成功了。</p>\n<p>上传到报名网站后，留意它自己的确认提示。有些网站会显示预览，用它确认图片显示正常。</p>\n<p>如果网站还是拒绝，先读清楚报错信息。它可能抱怨的是尺寸或格式，而不是大小，每种问题都有不同的修法。</p>\n<h2 id=\"choosing-dimensions\">压缩前先定好尺寸</h2>\n<p>尺寸和文件大小是联动的。图片越小，需要的数据就越少，达到50KB时画质损失也越小。</p>\n<p>先确认报名网站是否固定了尺寸。如果固定了，这个决定就替你做好了，不要和它较劲。</p>\n<p>如果尺寸自由，就选在显示尺寸下看起来还不错的最小尺寸。一张显示出来只有300像素宽的照片，没必要做到2000像素宽。</p>\n<p>缩小尺寸是你手里最有力的杠杆。宽高各减半，像素总数就只剩四分之一。</p>\n<p>能交给工具处理时就交给工具。它的分步缩放会先尝试原尺寸，只有目标要求时才缩小。</p>\n<h2 id=\"scanned-documents\">把扫描件压缩到50KB</h2>\n<p>扫描件和照片的表现不一样。它们基本是白底加深色文字，压缩效率非常高。</p>\n<p>不需要彩色时，就用灰度扫描。灰度扫描只携带三分之一的色彩数据，轻松就能到达50KB。</p>\n<p>压缩之前先清理扫描件。灰尘点和阴影会带入噪点，白白浪费KB。</p>\n<p>压缩后留意最小的文字。正文通常没问题，但脚注和印章可能会变虚。</p>\n<p>如果印章很重要，尺寸就留得宽裕一点。细小的彩色细节需要足够的像素才能认得出来。</p>\n<h2 id=\"heic-photos\">处理苹果手机的HEIC照片</h2>\n<p>苹果手机默认把照片存为HEIC。这些文件本身已经压得很好了，想压到50KB反而可能更难。</p>\n<p>直接把HEIC文件上传到工具。它能读取HEIC，并在压缩过程中完成转换，不需要单独的转换步骤。</p>\n<p>先在别的软件里把HEIC转成JPG，通常是白费功夫。这会在真正的压缩开始之前，就多加一轮有损处理。</p>\n<p>仔细检查结果。HEIC照片的细节往往很丰富，跳到50KB时，细腻的纹理可能比预想的更虚。</p>\n<p>如果结果看起来很粗糙，重试之前先把照片裁得更紧一点。裁得更近，脸部分到的有限预算就更多。</p>\n<h2 id=\"batch-50kb\">一次把多个文件压到50KB</h2>\n<p>很多表格需要两个文件：一张照片和一个签名。一起压缩能省时间，结果也更一致。</p>\n<p>把两个文件一次性加进工具。每个文件都会被单独压到50KB以下。</p>\n<p>以ZIP文件下载结果。解压到你存放申请材料的文件夹里。</p>\n<p>解压后逐个检查每个文件。签名和人像的需求不同，可能其中一个需要重试。</p>\n<p>上传之前先给解压出来的文件起好名字。照片和签名弄混了，是很尴尬又完全可以避免的错误。</p>\n<h2 id=\"verifying-before-submit\">提交前的最后检查清单</h2>\n<p>确认设备上显示的文件大小小于50KB。找一个48KB到49.9KB之间的数字。</p>\n<p>确认格式符合报名网站的规则。一个完美的WebP文件，在只接受JPG的网站上还是会失败。</p>\n<p>如果网站固定了尺寸，也要确认尺寸。打开图片属性，直接读取像素数。</p>\n<p>再把图片打开看一遍。用全尺寸检查脸部、文字和边缘。</p>\n<p>确认无误后再上传到报名网站。现在花两分钟检查，总比申请被退回要好。</p>\n<h2 id=\"group-photos\">50KB下的合影和拥挤画面</h2>\n<p>合影是50KB下最难的情况。每张脸都需要细节，二十张脸需要的细节就是一张脸的二十倍。</p>\n<p>把合影裁得尽可能紧。去掉空白的天空和地面，让脸部填满画面，分到最多的预算。</p>\n<p>接受一个现实：每个人的脸都会变柔和。50KB下的合影是活动的记录，不是每个人的肖像照。</p>\n<p>如果脸部必须保持可辨认，就用更大的尺寸。表格允许的话，合影应该用100KB或200KB。</p>\n<p>表格坚持要50KB时，优先保证整体构图。在这个体积下，清晰的整体布局比任何一张脸都重要。</p>\n<h2 id=\"file-naming\">给文件命名，再也不怕弄混</h2>\n<p>压缩工具常常给文件起通用的名字，而通用名字最容易出错。image-50kb.jpg这个名字，完全看不出是谁的照片。</p>\n<p>养成一个命名习惯：用途、人物、大小。比如visa-photo-ahmed-50kb.jpg，几个月后依然清楚，也不可能弄混。</p>\n<p>不同申请都用同一套格式。每个文件都按同一个结构命名，找文件时几秒钟就够了。</p>\n<p>把压缩好的文件和它所属的申请放在一起。躺在下载文件夹里的照片，就是一张等着被弄丢的照片。</p>\n<p>下载后立刻重命名，趁着用途还记得很清楚。过一阵子，你就想不起来这张照片是给哪份表格准备的了。</p>\n<h2 id=\"portal-previews\">用报名网站的预览再确认一次</h2>\n<p>很多报名网站上传后会显示预览。一定要用它。这个预览就是网站自己看到的图片，是发现问题的最后机会。</p>\n<p>检查照片的方向对不对。预览里照片是横的，说明网站读取方向的方式和你的手机不一样。</p>\n<p>检查脸部是否居中、是否完整。预览如果裁掉了边缘，可能会切掉下巴或额头。</p>\n<p>检查图片有没有被拉伸。有些网站会把上传的图片硬塞进固定画框，拉伸的脸在预览里一眼就能看出来。</p>\n<p>发现任何问题，都回去修原图。不要抱着“审核的人可能不会注意”的侥幸心理直接提交。</p>\n<p>想了解50KB上限存在的原因和压缩的原理，可以读<a href=\"/zh/blog/tu-pian-ya-suo-dao-50kb-wan-zheng-zhi-nan/\">图片压缩到50KB：完整指南</a>。提交前想先比较一下尺寸，可以看<a href=\"/zh/blog/50kb-vs-100kb-vs-200kb-xuan-na-ge-chi-cun/\">50KB、100KB、200KB选哪个尺寸？</a>。如果报名网站允许更大的文件，<a href=\"/zh/tupian-yasuo-dao-100kb/\">100KB压缩工具</a>能保留明显更多的细节。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"把图片压缩到50KB要花多长时间？","answer":"通常不到一分钟。二分画质搜索在普通手机或电脑上几秒钟就能跑完，慢的环节只可能是上传特别大的原图。一张10MB的照片比2MB的照片处理起来会稍慢一点。"},{"question":"能一次把多张照片都压到50KB吗？","answer":"可以，这个工具支持批量处理。一次加入多张图片，每张都会被单独压到50KB以下，然后一起打包成ZIP下载。报名表同时需要照片和签名时特别方便。"},{"question":"为什么下载下来的文件是48KB，而不是正好50KB？","answer":"工具是故意瞄准上限以下一点点，通常在48KB到49.9KB之间。报名系统按字节数判断，不同系统四舍五入的方式可能不一样，留出一点安全余量，就能避免文件在你的设备上通过、到了网站上却失败。"},{"question":"报名网站要求照片小于50KB、尺寸600×600像素，怎么做？","answer":"先用一张本来就接近正方形的照片，再交给工具处理尺寸。如果工具有尺寸控制选项，就设为600×600像素，格式保持JPG。下载后检查一下结果的尺寸，因为大小和尺寸是分开检查的。"},{"question":"压缩到50KB之前，要先把HEIC转成JPG吗？","answer":"不用，可以直接上传HEIC文件。工具能读取苹果手机的HEIC照片，在压缩过程中完成转换。直接上传原HEIC文件，效果比先在别的软件里转一次更好。"},{"question":"49KB的文件还是被报名网站拒绝了，怎么办？","answer":"先仔细读拒绝提示。问题常常出在格式或尺寸上，而不是大小。确认网站接受JPG还是WebP，核对要求的像素尺寸，再按字节数而不是设备上四舍五入后的数字重新检查文件大小。"}];
